-- =====================================================================
-- BachHome · service-product · dữ liệu mẫu
-- 367 sản phẩm điện gia dụng có thật, thu thập từ trang fptshop.com.vn
-- (tên, giá bán, thương hiệu, thông số, ảnh). Ảnh đã tải về frontend/public/products/fpt/.
-- Bảo hành để đồng loạt 12 tháng theo mức niêm yết chung của nhóm hàng gia dụng;
-- xuất xứ không có trong nguồn nên để trống thay vì điền số liệu tự nghĩ ra.
-- PLAIN SQL (không dùng khối thủ tục) để Spring Boot tách câu lệnh đúng theo dấu ";".
-- Chạy đúng một lần: nếu đã có sản phẩm ảnh /products/fpt/ thì toàn bộ khối bị bỏ qua.
-- =====================================================================

-- 0) Dọn danh mục cũ (dữ liệu mẫu đời đầu) trước khi nạp bộ mới.
DELETE FROM reviews WHERE NOT EXISTS (SELECT 1 FROM products WHERE image_url LIKE '/products/fpt/%');
DELETE FROM products WHERE NOT EXISTS (SELECT 1 FROM products p2 WHERE p2.image_url LIKE '/products/fpt/%');
DELETE FROM categories WHERE NOT EXISTS (SELECT 1 FROM products WHERE image_url LIKE '/products/fpt/%');

-- 1) Danh mục
INSERT INTO categories (id, name, description, active, display_order, created_at, updated_at)
SELECT v.id, v.name, v.description, true, v.ord, NOW(), NOW()
FROM (VALUES
    (1::bigint, 'Nồi chiên không dầu', 'Nồi chiên không dầu và nồi chiên hơi nước cho bữa ăn nhanh, ít dầu mỡ.', 1::int),
    (2::bigint, 'Bình đun & bình thủy điện', 'Bình đun siêu tốc, bình thủy điện giữ nhiệt cho gia đình và văn phòng.', 2::int),
    (3::bigint, 'Nồi điện đa năng', 'Nồi lẩu điện, nồi áp suất điện nấu nhanh và tiện lợi.', 3::int),
    (4::bigint, 'Đèn & chiếu sáng', 'Đèn điện, đèn năng lượng mặt trời và đèn pin sạc dự phòng.', 4::int),
    (5::bigint, 'Thiết bị sưởi ấm', 'Quạt sưởi, đèn sưởi giữ ấm cho mùa lạnh.', 5::int),
    (6::bigint, 'Bàn ủi & chăm sóc quần áo', 'Bàn ủi hơi nước, bàn ủi khô và tủ sấy quần áo.', 6::int),
    (7::bigint, 'Lò vi sóng', 'Lò vi sóng hâm nóng, rã đông và nướng nhanh.', 7::int),
    (8::bigint, 'Thiết bị điện khác', 'Ổ cắm điện, vợt bắt muỗi, máy rửa xe và các thiết bị gia dụng khác.', 8::int)
) AS v(id, name, description, ord)
WHERE NOT EXISTS (SELECT 1 FROM categories);

